export default [["q-fcps-bio4-01","Which molecule is the most potent allosteric activator of phosphofructokinase-1?",["Fructose 2,6-bisphosphate","Citrate","ATP","Glucagon"],"Fructose 2,6-bisphosphate, made by PFK-2 under insulin, activates PFK-1 and inhibits fructose 1,6-bisphosphatase."],["q-fcps-bio4-02","A child has severe lactic acidosis and neurological deterioration. Pyruvate dehydrogenase deficiency is suspected. Which dietary change helps?",["High-fat, low-carbohydrate (ketogenic) diet","High-carbohydrate diet","High-protein with leucine","Fructose supplementation"],"Pyruvate cannot enter the TCA cycle, so avoiding carbohydrate reduces lactate. Ketones provide acetyl-CoA directly, and lysine and leucine are purely ketogenic."],["q-fcps-bio4-03","Which inhibitor of the electron transport chain blocks complex I?",["Rotenone","Antimycin A","Cyanide","Oligomycin"],"Rotenone inhibits NADH-coenzyme Q oxidoreductase. Antimycin A blocks complex III, cyanide and carbon monoxide block complex IV, and oligomycin blocks ATP synthase."],["q-fcps-bio4-04","Oligomycin inhibits oxidative phosphorylation by:",["Blocking the proton channel of ATP synthase","Inhibiting complex IV","Dissipating the proton gradient","Inhibiting the adenine nucleotide translocase only"],"Oligomycin binds the F0 subunit, so protons cannot flow back and electron transport stalls because the gradient builds up."],["q-fcps-bio4-05","Thermogenin (UCP1) in brown adipose tissue produces heat by:",["Dissipating the proton gradient across the inner mitochondrial membrane","Inhibiting complex III","Stimulating ATP synthase","Increasing glycolysis"],"UCP1 provides a proton leak that uncouples respiration from ATP synthesis and releases energy as heat, which is important in neonates."],["q-fcps-bio4-06","Which glucose transporter is insulin-dependent?",["GLUT4","GLUT1","GLUT2","GLUT3"],"GLUT4 in skeletal muscle and adipose tissue moves to the membrane in response to insulin. GLUT2 is in the liver, pancreatic beta cells and kidney."],["q-fcps-bio4-07","Which transporter allows pancreatic beta cells to sense glucose?",["GLUT2","GLUT4","SGLT1","GLUT5"],"GLUT2 is a high-capacity, low-affinity transporter, so intracellular glucose follows plasma levels and drives insulin release."],["q-fcps-bio4-08","Which enzyme is activated by cAMP-dependent phosphorylation to promote glycogen breakdown?",["Phosphorylase kinase, activating glycogen phosphorylase","Glycogen synthase","Protein phosphatase 1","Branching enzyme"],"Glucagon and adrenaline raise cAMP and activate protein kinase A, which phosphorylates phosphorylase kinase and in turn glycogen phosphorylase, while inactivating glycogen synthase."],["q-fcps-bio4-09","McArdle disease results from deficiency of:",["Muscle glycogen phosphorylase","Glucose-6-phosphatase","Acid alpha-glucosidase","Debranching enzyme"],"Muscle glycogen cannot be broken down, causing exercise intolerance with a second-wind phenomenon and no rise in lactate."],["q-fcps-bio4-10","Cori disease (type III glycogen storage disease) is caused by deficiency of:",["Debranching enzyme","Branching enzyme","Glucose-6-phosphatase","Lysosomal acid maltase"],"Absent debranching enzyme leaves limit dextrins, and gluconeogenesis is intact, so hypoglycaemia is milder than in von Gierke disease."],["q-fcps-bio4-11","Which enzyme of the urea cycle is the committed regulated step and is activated by N-acetylglutamate?",["Carbamoyl phosphate synthetase I","Ornithine transcarbamylase","Arginase","Argininosuccinate synthetase"],"CPS-I in mitochondria is activated allosterically by N-acetylglutamate, which rises when amino acid catabolism increases."],["q-fcps-bio4-12","Sodium benzoate and sodium phenylbutyrate are used in hyperammonaemia because they:",["Provide alternative pathways for nitrogen excretion","Inhibit glutaminase","Stimulate the urea cycle enzymes","Increase renal ammonia reabsorption"],"Benzoate conjugates with glycine and phenylacetate with glutamine, forming compounds that are excreted in urine and carry away nitrogen."],["q-fcps-bio4-13","Which amino acid disorder presents with a musty odour, fair skin and intellectual disability if untreated?",["Phenylketonuria","Maple syrup urine disease","Homocystinuria","Alkaptonuria"],"Phenylalanine hydroxylase or tetrahydrobiopterin deficiency causes phenylalanine accumulation, so tyrosine becomes essential and melanin is reduced."],["q-fcps-bio4-14","Which enzyme is rate-limiting in catecholamine synthesis?",["Tyrosine hydroxylase","DOPA decarboxylase","Dopamine beta-hydroxylase","Phenylethanolamine N-methyltransferase"],"Tyrosine hydroxylase is inhibited by dopamine and noradrenaline through end-product feedback."],["q-fcps-bio4-15","Vitamin B6 is required as a coenzyme for:",["Transamination and decarboxylation reactions","Carboxylation reactions","One-carbon transfer","Hydroxylation of proline"],"Pyridoxal phosphate is the coenzyme for aminotransferases, GABA and serotonin synthesis, haem synthesis and glycogen phosphorylase."],["q-fcps-bio4-16","Isoniazid causes peripheral neuropathy by depleting:",["Pyridoxine (vitamin B6)","Thiamine","Niacin","Riboflavin"],"Isoniazid binds pyridoxal and increases its excretion, so pyridoxine is given prophylactically."],["q-fcps-bio4-17","Which is the rate-limiting enzyme of haem synthesis in the liver?",["ALA synthase","ALA dehydratase","Ferrochelatase","Porphobilinogen deaminase"],"ALA synthase requires pyridoxal phosphate and is repressed by haem and induced by barbiturates and other drugs in acute porphyrias."],["q-fcps-bio4-18","Crigler-Najjar syndrome type I is caused by absence of:",["UDP-glucuronosyltransferase 1A1","Haem oxygenase","Biliverdin reductase","Bilirubin oxidase"],"Without conjugation, unconjugated bilirubin accumulates and can cause kernicterus. Gilbert syndrome is a mild reduction of the same enzyme."],["q-fcps-bio4-19","A patient has raised conjugated bilirubin, a black liver on biopsy and normal liver enzymes. The diagnosis is:",["Dubin-Johnson syndrome","Gilbert syndrome","Rotor syndrome","Crigler-Najjar type II"],"Dubin-Johnson syndrome is a defect of MRP2 canalicular export, giving conjugated hyperbilirubinaemia and a pigmented liver."],["q-fcps-bio4-20","Which hormone is the master regulator of iron absorption and is raised in inflammation?",["Hepcidin","Erythropoietin","Transferrin","Ferritin"],"Hepcidin blocks ferroportin, trapping iron in enterocytes and macrophages and causing the anaemia of chronic disease."],["q-fcps-bio4-21","Wilson disease is characterised by:",["Low serum ceruloplasmin and raised urinary copper","High serum ceruloplasmin","Low urinary copper","Iron overload"],"ATP7B deficiency impairs biliary copper excretion and ceruloplasmin incorporation, causing hepatic, neurological and corneal copper deposition."],["q-fcps-bio4-22","Menkes disease results from a mutation in the gene for a copper-transporting ATPase. Which enzyme is deficient, producing kinky hair?",["Lysyl oxidase","Prolyl hydroxylase","Tyrosinase only","Superoxide dismutase only"],"Reduced copper impairs lysyl oxidase and cross-linking of collagen and elastin, with neurodegeneration and brittle hair."],["q-fcps-bio4-23","Which vitamin is a lipid-soluble antioxidant protecting red cell membranes?",["Vitamin E","Vitamin C","Vitamin K","Vitamin D"],"Tocopherol stops lipid peroxidation, and deficiency causes haemolytic anaemia and neuropathy, especially in fat malabsorption."],["q-fcps-bio4-24","Retinoic acid acts as a:",["Ligand for nuclear receptors regulating gene transcription","Visual pigment","Coenzyme in carboxylation","Cofactor in collagen synthesis"],"Retinoic acid binds RAR and RXR receptors and controls differentiation of epithelia, while retinal is the visual chromophore."],["q-fcps-bio4-25","Which vitamin deficiency causes megaloblastic anaemia WITHOUT neurological signs?",["Folate","Vitamin B12","Vitamin B6","Vitamin C"],"Folate deficiency impairs thymidylate synthesis, but only B12 deficiency causes demyelination through methylmalonyl-CoA accumulation."],["q-fcps-bio4-26","Methotrexate inhibits which enzyme?",["Dihydrofolate reductase","Thymidylate synthase","Ribonucleotide reductase","Xanthine oxidase"],"Methotrexate blocks regeneration of tetrahydrofolate, so purine and thymidylate synthesis falls."],["q-fcps-bio4-27","Biotin is a coenzyme for which enzyme?",["Pyruvate carboxylase","Pyruvate dehydrogenase","Transketolase","Glutathione reductase"],"Biotin-dependent carboxylases include pyruvate carboxylase, acetyl-CoA carboxylase and propionyl-CoA carboxylase."],["q-fcps-bio4-28","Which enzyme converts homocysteine to methionine and needs vitamin B12?",["Methionine synthase","Cystathionine beta-synthase","Methylmalonyl-CoA mutase","Serine hydroxymethyltransferase"],"Methionine synthase transfers a methyl group from methyltetrahydrofolate, so B12 deficiency traps folate and raises homocysteine."],["q-fcps-bio4-29","Methylmalonic aciduria is typical of which deficiency?",["Vitamin B12","Folate","Thiamine","Vitamin B6"],"Methylmalonyl-CoA mutase requires adenosylcobalamin, so methylmalonic acid is raised only in B12 deficiency."],["q-fcps-bio4-30","Familial type III hyperlipoproteinaemia (dysbetalipoproteinaemia) is associated with a defect in:",["Apolipoprotein E","Lipoprotein lipase","LDL receptor","Apolipoprotein A-I"],"Abnormal ApoE2 impairs hepatic uptake of chylomicron and VLDL remnants, causing palmar xanthomas and raised cholesterol and triglycerides."],["q-fcps-bio4-31","Chylomicronaemia with eruptive xanthomas and pancreatitis in a child is typical of:",["Lipoprotein lipase or ApoC-II deficiency","LDL receptor defect","ApoB-100 defect","Tangier disease"],"Without lipoprotein lipase activity chylomicrons accumulate, plasma is milky and triglycerides are extremely high."],["q-fcps-bio4-32","Abetalipoproteinaemia is caused by a defect in:",["Microsomal triglyceride transfer protein","Lipoprotein lipase","LCAT","ABCA1"],"Without apoB-containing lipoprotein assembly, patients have fat malabsorption, acanthocytes and deficiencies of fat-soluble vitamins."],["q-fcps-bio4-33","Tangier disease is due to a defect in:",["ABCA1 cholesterol efflux transporter","LCAT","CETP","Hepatic lipase"],"Defective ABCA1 reduces HDL and cholesterol accumulates in macrophages, giving orange tonsils and neuropathy."],["q-fcps-bio4-34","Which lipid storage disease causes a cherry-red macula and sphingomyelin accumulation with hepatosplenomegaly?",["Niemann-Pick disease","Tay-Sachs disease","Fabry disease","Krabbe disease"],"Niemann-Pick disease is deficiency of sphingomyelinase, with foam cells and neurodegeneration. Unlike Tay-Sachs it causes organomegaly."],["q-fcps-bio4-35","Globoid cells and absence of myelin with irritability and developmental regression in an infant suggest deficiency of:",["Galactocerebrosidase","Arylsulfatase A","Hexosaminidase A","Beta-glucosidase"],"Krabbe disease results from galactocerebrosidase deficiency, with accumulation of psychosine that destroys oligodendrocytes."],["q-fcps-bio4-36","Hurler syndrome is a mucopolysaccharidosis caused by deficiency of:",["Alpha-L-iduronidase","Iduronate sulfatase","Heparan sulfamidase","Beta-glucuronidase"],"Hurler syndrome has corneal clouding, coarse features and developmental delay. Hunter syndrome (X-linked iduronate sulfatase deficiency) has no corneal clouding."],["q-fcps-bio4-37","I-cell disease is caused by failure of:",["Phosphorylation of mannose residues on lysosomal enzymes","Glycosylation of collagen","Degradation of glycosaminoglycans","Peroxisomal import"],"Lack of mannose 6-phosphate tagging sends lysosomal enzymes out of the cell, so inclusion bodies accumulate in fibroblasts."],["q-fcps-bio4-38","Zellweger syndrome is a disorder of which organelle?",["Peroxisome","Lysosome","Mitochondrion","Golgi apparatus"],"Peroxisomal biogenesis failure causes accumulation of very long chain fatty acids, hypotonia and liver disease."],["q-fcps-bio4-39","Carnitine is required for:",["Transport of long-chain fatty acids into mitochondria","Fatty acid synthesis","Ketone body synthesis","Cholesterol synthesis"],"Carnitine palmitoyltransferase I is the regulated step, inhibited by malonyl-CoA."],["q-fcps-bio4-40","Which deficiency causes salt wasting, ambiguous genitalia in a girl and raised 17-hydroxyprogesterone?",["21-hydroxylase","11-beta-hydroxylase","17-alpha-hydroxylase","3-beta-hydroxysteroid dehydrogenase"],"21-hydroxylase deficiency blocks cortisol and aldosterone and diverts precursors to androgens."],["q-fcps-bio4-41","11-beta-hydroxylase deficiency produces virilisation with:",["Hypertension","Hypotension","Hypokalaemia with hypotension","Hyperkalaemia"],"Accumulated 11-deoxycorticosterone has mineralocorticoid activity, causing hypertension and hypokalaemia."],["q-fcps-bio4-42","Adenosine deaminase deficiency causes:",["Severe combined immunodeficiency","Gout","Megaloblastic anaemia","Orotic aciduria"],"Accumulation of deoxyadenosine and dATP is toxic to lymphocytes, impairing both T and B cell development."],["q-fcps-bio4-43","A child has megaloblastic anaemia and orotic aciduria without hyperammonaemia. The defect is in:",["UMP synthase","Ornithine transcarbamylase","Dihydrofolate reductase","Thymidylate synthase"],"Hereditary orotic aciduria is a defect of pyrimidine synthesis and responds to uridine. In OTC deficiency orotic acid is raised with hyperammonaemia."],["q-fcps-bio4-44","Which enzyme is inhibited by hydroxyurea?",["Ribonucleotide reductase","Dihydrofolate reductase","Xanthine oxidase","Thymidylate synthase"],"Ribonucleotide reductase converts ribonucleotides to deoxyribonucleotides, so inhibition lowers dNTP pools for DNA synthesis."],["q-fcps-bio4-45","Which DNA repair pathway is defective in hereditary non-polyposis colorectal cancer (Lynch syndrome)?",["Mismatch repair","Nucleotide excision repair","Base excision repair","Homologous recombination"],"Mutations in MLH1, MSH2, MSH6 or PMS2 cause microsatellite instability."],["q-fcps-bio4-46","Which enzyme relieves supercoiling during DNA replication and is targeted by fluoroquinolones in bacteria?",["Topoisomerase II (DNA gyrase)","Helicase","Primase","DNA ligase"],"Gyrase introduces negative supercoils and quinolones trap the enzyme-DNA complex."],["q-fcps-bio4-47","Which feature of the genetic code explains that several codons can code for the same amino acid?",["Degeneracy","Universality","Non-overlapping","Commaless"],"Most amino acids have more than one codon, often differing at the third (wobble) position."],["q-fcps-bio4-48","A point mutation that changes a codon to a stop codon is called:",["Nonsense mutation","Missense mutation","Silent mutation","Frameshift mutation"],"A nonsense mutation causes premature termination and usually a truncated, non-functional protein."],["q-fcps-bio4-49","Deletion of three nucleotides in a coding sequence, as in the commonest cystic fibrosis mutation, leads to:",["Loss of one amino acid without a frameshift","A frameshift","A nonsense codon","Silent change"],"Deletion of a multiple of three nucleotides removes amino acids but preserves the reading frame."],["q-fcps-bio4-50","Fragile X syndrome is caused by expansion of which trinucleotide repeat?",["CGG","CAG","GAA","CTG"],"CGG repeats in FMR1 lead to methylation and silencing. Huntington is CAG, Friedreich ataxia is GAA and myotonic dystrophy is CTG."],["q-fcps-bio4-51","Prader-Willi syndrome results from loss of function of the:",["Paternal copy of chromosome 15q11-13","Maternal copy of chromosome 15q11-13","Paternal chromosome 7","X chromosome"],"It is caused by paternal deletion or maternal uniparental disomy. Loss of the maternal copy causes Angelman syndrome."],["q-fcps-bio4-52","Leber hereditary optic neuropathy shows which pattern of inheritance?",["Mitochondrial (maternal)","Autosomal dominant","X-linked recessive","Autosomal recessive"],"Mitochondrial DNA is inherited from the mother, so all children of an affected mother can carry the mutation."],["q-fcps-bio4-53","In a population in Hardy-Weinberg equilibrium the carrier frequency of an autosomal recessive disease with incidence 1 in 10,000 is about:",["1 in 50","1 in 100","1 in 10","1 in 500"],"q squared is 1 in 10,000, so q is 1 in 100 and 2pq is about 2 in 100, which is 1 in 50."],["q-fcps-bio4-54","The Southern blot is used to detect:",["DNA","RNA","Proteins","Lipids"],"Southern blotting detects DNA, Northern blotting detects RNA and Western blotting detects proteins."],["q-fcps-bio4-55","Which technique amplifies a specific DNA sequence?",["Polymerase chain reaction","Western blot","ELISA","Flow cytometry"],"PCR uses repeated cycles of denaturation, annealing and extension with a heat-stable polymerase."],["q-fcps-bio4-56","The Km of an enzyme is the:",["Substrate concentration at half of maximal velocity","Maximal velocity","Substrate concentration at maximal velocity","Inhibitor concentration at half-maximal inhibition"],"A low Km indicates high affinity for the substrate."],["q-fcps-bio4-57","A competitive inhibitor on a Lineweaver-Burk plot:",["Increases Km without changing Vmax","Decreases Vmax without changing Km","Decreases both Km and Vmax","Increases Vmax"],"Competitive inhibition can be overcome by raising substrate, so the apparent Km increases and the lines intersect on the y axis."],["q-fcps-bio4-58","Which isoenzyme of lactate dehydrogenase is predominant in the heart?",["LDH-1","LDH-5","LDH-3","LDH-2 only"],"LDH-1 (H4) predominates in cardiac muscle and red cells, and LDH-5 (M4) in liver and skeletal muscle."],["q-fcps-bio4-59","The protein structure that is stabilised mainly by hydrogen bonds between backbone atoms is the:",["Secondary structure","Primary structure","Tertiary structure","Quaternary structure"],"Alpha helices and beta sheets are held by backbone hydrogen bonds."],["q-fcps-bio4-60","Prion diseases involve conversion of a protein from a predominantly:",["Alpha helix to beta sheet","Beta sheet to alpha helix","Random coil to alpha helix","Disulphide-bonded to reduced form"],"PrP-sc is rich in beta sheet, is protease resistant and templates conversion of normal PrP-c."],["q-fcps-bio4-61","Cholera toxin causes diarrhoea by:",["ADP-ribosylating Gs and keeping adenylyl cyclase permanently active","ADP-ribosylating Gi","Inhibiting Na-K-ATPase","Blocking chloride channels directly"],"Raised cAMP opens the CFTR channel and causes secretion of chloride and water. Pertussis toxin inactivates Gi."],["q-fcps-bio4-62","Which second messenger is generated from PIP2 by phospholipase C and releases calcium from the endoplasmic reticulum?",["IP3","DAG","cAMP","cGMP"],"IP3 binds receptors on the endoplasmic reticulum, and DAG activates protein kinase C."],["q-fcps-bio4-63","Nitric oxide is synthesised from:",["Arginine","Glutamine","Tyrosine","Tryptophan"],"Nitric oxide synthase converts arginine to citrulline and NO, which activates guanylyl cyclase and raises cGMP."],["q-fcps-bio4-64","During prolonged fasting for more than 3 days the brain obtains most of its energy from:",["Ketone bodies","Glucose","Free fatty acids","Amino acids"],"Ketones cross the blood-brain barrier and spare glucose and muscle protein."],["q-fcps-bio4-65","Which enzyme in the liver is responsible for the first step of ethanol oxidation?",["Alcohol dehydrogenase","Aldehyde dehydrogenase","CYP2E1 only","Catalase only"],"Alcohol dehydrogenase converts ethanol to acetaldehyde with production of NADH, which promotes lactic acidosis, hypoglycaemia and fatty liver."],["q-fcps-bio4-66","Kwashiorkor differs from marasmus in that it shows:",["Oedema and fatty liver with relatively preserved subcutaneous fat","Severe wasting with no oedema","Normal albumin","Increased appetite only"],"Protein deficiency with adequate calories lowers albumin and causes oedema, while marasmus is global energy deficiency."],["q-fcps-bio4-67","The respiratory quotient of pure carbohydrate oxidation is:",["1.0","0.7","0.8","0.5"],"Carbohydrate gives an RQ of 1.0, fat 0.7 and protein about 0.8."],["q-fcps-bio4-68","Selenium is an essential cofactor for:",["Glutathione peroxidase","Superoxide dismutase","Catalase","Cytochrome oxidase"],"Selenocysteine is part of glutathione peroxidase and the deiodinases."],["q-fcps-bio4-69","Zinc deficiency causes:",["Acrodermatitis enteropathica with poor wound healing","Goitre","Pellagra","Scurvy"],"Zinc is a cofactor for many enzymes, and deficiency causes perioral and acral dermatitis, alopecia, diarrhoea and impaired immunity."],["q-fcps-bio5-01","Which enzyme phosphorylates glucose in the liver and has a high Km, so that it acts only when blood glucose is high?",["Glucokinase","Hexokinase","Phosphofructokinase-1","Pyruvate kinase"],"Glucokinase is induced by insulin and is not inhibited by glucose 6-phosphate, so the liver takes up glucose after a meal."],["q-fcps-bio5-02","Hexokinase differs from glucokinase in that hexokinase:",["Has a low Km and is inhibited by glucose 6-phosphate","Is found only in the liver","Is induced by insulin","Has a high Vmax"],"Hexokinase in most tissues saturates at low glucose and so works even in fasting."],["q-fcps-bio5-03","Which compound in red cells shifts the oxygen dissociation curve to the right and is produced by a side reaction of glycolysis?",["2,3-Bisphosphoglycerate","Pyruvate","Lactate","Phosphoenolpyruvate"],"The Rapoport-Luebering shunt generates 2,3-BPG from 1,3-BPG, and it reduces oxygen affinity."],["q-fcps-bio5-04","A red cell with pyruvate kinase deficiency has:",["Reduced ATP and haemolytic anaemia","Increased ATP","Increased glutathione","Normal glycolysis"],"Without net ATP from glycolysis, red cells cannot maintain the sodium pump, so they become rigid and haemolyse."],["q-fcps-bio5-05","Which enzyme is shared between glycolysis and gluconeogenesis?",["Phosphoglycerate kinase","Pyruvate kinase","Phosphofructokinase-1","Hexokinase"],"The three irreversible steps of glycolysis (hexokinase, PFK-1, pyruvate kinase) are bypassed by glucose 6-phosphatase, fructose 1,6-bisphosphatase and PEP carboxykinase with pyruvate carboxylase."],["q-fcps-bio5-06","Which of these cannot be converted to glucose in humans?",["Acetyl-CoA from fatty acids","Lactate","Glycerol","Alanine"],"Mammals cannot convert acetyl-CoA to pyruvate or oxaloacetate, so even-chain fatty acids are not gluconeogenic."],["q-fcps-bio5-07","Which enzyme of the TCA cycle is the main regulatory point and is inhibited by ATP and NADH?",["Isocitrate dehydrogenase","Fumarase","Malate dehydrogenase","Succinyl-CoA synthetase"],"Isocitrate dehydrogenase is activated by ADP and calcium, and it links energy status to the cycle."],["q-fcps-bio5-08","Which enzyme in the TCA cycle produces GTP (or ATP) by substrate-level phosphorylation?",["Succinyl-CoA synthetase","Succinate dehydrogenase","Alpha-ketoglutarate dehydrogenase","Citrate synthase"],"Conversion of succinyl-CoA to succinate yields GTP."],["q-fcps-bio5-09","How many ATP are produced per NADH through oxidative phosphorylation (P/O ratio), approximately?",["2.5","1.5","3.5","4"],"FADH2 yields about 1.5 ATP, and the complete oxidation of glucose gives about 30 to 32 ATP."],["q-fcps-bio5-10","Which shuttle transfers cytosolic NADH reducing equivalents into mitochondria in the liver and heart?",["Malate-aspartate shuttle","Glycerol 3-phosphate shuttle","Carnitine shuttle","Citrate shuttle"],"The glycerol 3-phosphate shuttle is used in skeletal muscle and the brain and gives FADH2, so it yields less ATP."],["q-fcps-bio5-11","Diabetic cataract is caused by accumulation of:",["Sorbitol in the lens","Galactose","Fructose","Glycogen"],"Aldose reductase converts glucose to sorbitol, which is not readily metabolised and draws water into the lens."],["q-fcps-bio5-12","Which enzyme converts glucose to sorbitol in the polyol pathway?",["Aldose reductase","Sorbitol dehydrogenase","Hexokinase","Fructokinase"],"Tissues lacking sorbitol dehydrogenase, such as the lens, retina, Schwann cells and kidney, accumulate sorbitol."],["q-fcps-bio5-13","Glycogen synthesis uses which activated sugar donor?",["UDP-glucose","ADP-glucose","Glucose 1-phosphate","GDP-glucose"],"Glycogen synthase adds glucose from UDP-glucose to the nonreducing ends of the growing chain."],["q-fcps-bio5-14","Pompe disease is deficiency of:",["Lysosomal acid alpha-glucosidase","Glucose 6-phosphatase","Muscle phosphorylase","Debranching enzyme"],"Lysosomal glycogen accumulates in the heart and muscle, so infants have cardiomegaly and hypotonia."],["q-fcps-bio5-15","Which enzyme converts arachidonic acid to leukotrienes?",["5-Lipoxygenase","Cyclooxygenase","Phospholipase A2","Thromboxane synthase"],"5-Lipoxygenase produces LTB4 (a neutrophil chemoattractant) and LTC4 and LTD4 (bronchoconstrictors)."],["q-fcps-bio5-16","Corticosteroids reduce inflammation by:",["Inducing lipocortin, which inhibits phospholipase A2","Inhibiting COX-2 directly","Inhibiting 5-lipoxygenase directly","Blocking histamine receptors"],"By blocking phospholipase A2 they reduce both prostaglandin and leukotriene synthesis."],["q-fcps-bio5-17","The main component of pulmonary surfactant is:",["Dipalmitoylphosphatidylcholine","Sphingomyelin","Cholesterol","Phosphatidylserine"],"A lecithin-to-sphingomyelin ratio above 2 in amniotic fluid indicates fetal lung maturity."],["q-fcps-bio5-18","Which amino acid is the donor of the amino group in most transamination reactions, as it forms alpha-ketoglutarate?",["Glutamate","Aspartate","Alanine","Glycine"],"Transaminases transfer an amino group to alpha-ketoglutarate to form glutamate, and they need pyridoxal phosphate."],["q-fcps-bio5-19","An AST to ALT ratio above 2 suggests:",["Alcoholic hepatitis","Viral hepatitis","Myocardial infarction","Obstructive jaundice"],"In viral hepatitis ALT is usually higher than AST, while in alcoholic liver disease AST is higher and GGT is raised."],["q-fcps-bio5-20","Which amino acids are purely ketogenic?",["Leucine and lysine","Alanine and glycine","Phenylalanine and tyrosine","Aspartate and glutamate"],"They are degraded only to acetyl-CoA or acetoacetate, and so they cannot give net glucose."],["q-fcps-bio5-21","Histamine is formed from histidine by:",["Decarboxylation","Deamination","Hydroxylation","Transamination"],"Histidine decarboxylase requires pyridoxal phosphate."],["q-fcps-bio5-22","Glycine is a precursor of all of the following EXCEPT:",["Catecholamines","Haem","Creatine","Glutathione"],"Catecholamines come from tyrosine, while haem, purines, creatine, glutathione and bile salt conjugates use glycine."],["q-fcps-bio5-23","The conversion of tyrosine to melanin requires:",["Tyrosinase","Tyrosine hydroxylase","Phenylalanine hydroxylase","Tyrosine aminotransferase"],"Tyrosinase deficiency causes oculocutaneous albinism."],["q-fcps-bio5-24","Hartnup disease is caused by a defect in the transport of neutral amino acids, leading to deficiency of:",["Niacin (from tryptophan)","Thiamine","Vitamin B12","Folate"],"Tryptophan is the precursor of niacin, so patients develop a pellagra-like rash and ataxia."],["q-fcps-bio5-25","Which compound is the universal methyl donor in the body?",["S-adenosylmethionine","Tetrahydrofolate","Betaine","Methylcobalamin"],"SAM is synthesised from methionine and ATP."],["q-fcps-bio5-26","Which enzyme of the urea cycle is located in the cytosol and requires aspartate?",["Argininosuccinate synthetase","Ornithine transcarbamylase","Carbamoyl phosphate synthetase I","Mitochondrial glutaminase"],"Citrulline condenses with aspartate in the cytosol in an ATP-dependent reaction."],["q-fcps-bio5-27","Which amino acid is the main carrier of nitrogen from muscle to the liver during fasting?",["Alanine","Glutamate","Arginine","Aspartate"],"The glucose-alanine cycle carries pyruvate nitrogen from muscle to the liver for urea synthesis and gluconeogenesis."],["q-fcps-bio5-28","Which enzyme is the committed step of purine synthesis?",["Glutamine-PRPP amidotransferase","Adenylosuccinate synthetase","Xanthine oxidase","IMP dehydrogenase"],"It is feedback-inhibited by AMP, GMP and IMP."],["q-fcps-bio5-29","Purines are degraded to:",["Uric acid","Urea","Allantoin","Orotic acid"],"Humans lack uricase, and so the end product is uric acid, and allantoin is the product in most other mammals."],["q-fcps-bio5-30","Which drug inhibits xanthine oxidase and reduces uric acid synthesis?",["Allopurinol","Probenecid","Colchicine","Rasburicase"],"Rasburicase is a recombinant uricase and it converts uric acid to the soluble allantoin."],["q-fcps-bio5-31","The enzyme that synthesises a short RNA primer during DNA replication is:",["Primase","DNA polymerase III","Helicase","Ligase"],"DNA polymerase cannot start a chain de novo, so it needs the primer to give a free 3' OH."],["q-fcps-bio5-32","The main replicative enzyme in prokaryotes is:",["DNA polymerase III","DNA polymerase I","DNA polymerase II","RNA polymerase"],"Polymerase I removes the RNA primers with its 5' to 3' exonuclease activity and fills the gap."],["q-fcps-bio5-33","Telomerase is a:",["Ribonucleoprotein with reverse transcriptase activity","DNA helicase","Topoisomerase","DNA ligase"],"It extends the 3' ends of chromosomes using its own RNA template, and it is reactivated in most cancers."],["q-fcps-bio5-34","Which repair pathway fixes double-strand DNA breaks and involves BRCA1 and BRCA2?",["Homologous recombination","Base excision repair","Nucleotide excision repair","Mismatch repair"],"BRCA-deficient tumours are sensitive to PARP inhibitors because of synthetic lethality."],["q-fcps-bio5-35","The TATA box is a site that:",["Binds general transcription factors upstream of the gene","Terminates transcription","Encodes a start codon","Serves as an origin of replication"],"It lies about 25 to 30 bases upstream of the transcription start site in many eukaryotic promoters."],["q-fcps-bio5-36","Eukaryotic mRNA processing includes all of the following EXCEPT:",["Addition of a Shine-Dalgarno sequence","5' capping","3' polyadenylation","Splicing"],"The Shine-Dalgarno sequence is a bacterial ribosome-binding site."],["q-fcps-bio5-37","Anti-Smith antibodies in SLE are directed against:",["snRNPs of the spliceosome","Centromere proteins","Histones","Topoisomerase I"],"Spliceosome components remove introns from pre-mRNA."],["q-fcps-bio5-38","Which codon is the usual start codon in eukaryotes?",["AUG","UAA","UGA","GUG only"],"AUG codes for methionine, and UAA, UAG and UGA are stop codons."],["q-fcps-bio5-39","Aminoacyl-tRNA synthetases are important for the accuracy of translation because they:",["Attach the correct amino acid to its cognate tRNA","Form peptide bonds","Translocate the ribosome","Release the polypeptide"],"They carry out proofreading, and the tRNA anticodon pairs with the mRNA codon."],["q-fcps-bio5-40","Peptide bond formation in the ribosome is catalysed by:",["Peptidyl transferase activity of the large subunit rRNA","Elongation factor EF-Tu","Release factor","tRNA synthetase"],"The ribozyme activity of the 23S (bacterial) or 28S (eukaryotic) rRNA forms the bond."],["q-fcps-bio5-41","The signal recognition particle is involved in:",["Targeting ribosomes making secretory proteins to the endoplasmic reticulum","Nuclear import","Mitochondrial import","Lysosomal enzyme tagging"],"A signal peptide on the nascent chain is recognised and the ribosome docks on the rough ER."],["q-fcps-bio5-42","Gamma-carboxylation of glutamate residues is required for the function of:",["Clotting factors II, VII, IX and X","Collagen","Fibrinogen","Albumin"],"Vitamin K is a cofactor for the carboxylase, and warfarin blocks its regeneration."],["q-fcps-bio5-43","In the lac operon, in the presence of lactose and absence of glucose:",["The operon is transcribed at a high level","The operon is repressed","Allolactose binds the CAP","cAMP is low"],"Allolactose releases the repressor, and the high cAMP-CAP complex enhances transcription."],["q-fcps-bio5-44","Methylation of CpG islands in a gene promoter usually results in:",["Gene silencing","Gene activation","No effect","Gene duplication"],"It is an epigenetic mechanism that is important in imprinting, X-inactivation and cancer."],["q-fcps-bio5-45","Histone acetylation generally:",["Loosens chromatin and increases transcription","Condenses chromatin","Represses transcription","Causes DNA methylation"],"Histone acetyltransferases neutralise the positive charge of lysines, so histones bind DNA less tightly."],["q-fcps-bio5-46","ELISA is used for:",["Detecting antigen or antibody using an enzyme-linked antibody","Sequencing DNA","Amplifying DNA","Separating chromosomes"],"The enzyme converts a substrate to a coloured product, and HIV screening uses it."],["q-fcps-bio5-47","Fluorescence in situ hybridisation (FISH) can detect:",["Specific chromosomal deletions and translocations","Protein levels","Point mutations in all genes","Enzyme activity"],"Labelled DNA probes bind complementary sequences on metaphase or interphase chromosomes."],["q-fcps-bio5-48","CRISPR-Cas9 genome editing uses a guide RNA to:",["Direct the Cas9 nuclease to a specific DNA sequence","Repair DNA","Synthesise proteins","Replicate DNA"],"Cas9 creates a double-strand break, and the cell repairs it, allowing gene knockout or editing."],["q-fcps-bio5-49","Anticipation in genetic disease is seen in:",["Trinucleotide repeat disorders","Autosomal recessive disorders","Mitochondrial disorders","Chromosomal deletions"],"The repeat expands in successive generations so the disease appears earlier and is more severe."],["q-fcps-bio5-50","The proportion of individuals with a given genotype who show the phenotype is called:",["Penetrance","Expressivity","Pleiotropy","Heterogeneity"],"Expressivity is the variation in severity among those who do show the phenotype."],["q-fcps-bio5-51","A condition in which a single gene mutation produces multiple unrelated phenotypic effects is:",["Pleiotropy","Epistasis","Mosaicism","Anticipation"],"Marfan syndrome and PKU are examples of pleiotropy."],["q-fcps-bio5-52","Which enzyme class catalyses the transfer of functional groups between molecules?",["Transferase","Ligase","Isomerase","Lyase"],"Oxidoreductases transfer electrons, hydrolases cleave with water, lyases cleave without water, isomerases rearrange and ligases join with ATP."],["q-fcps-bio5-53","The free energy change of a reaction at equilibrium is:",["Zero","Positive","Negative","Equal to the standard free energy"],"A reaction proceeds spontaneously when delta G is negative, and coupling with ATP hydrolysis can drive unfavourable reactions."],["q-fcps-bio5-54","Which compound acts as the immediate energy store in muscle that regenerates ATP?",["Creatine phosphate","Glycogen","Triglyceride","Lactate"],"Creatine kinase transfers phosphate from creatine phosphate to ADP, and creatinine is its breakdown product."],["q-fcps-bio5-55","Creatinine excretion is proportional to:",["Muscle mass","Dietary protein intake only","Liver function","Urine volume"],"Serum creatinine is therefore an estimate of GFR but it is affected by muscle mass."],["q-fcps-bio5-56","Which vitamin is needed for the visual cycle and for differentiation of epithelial cells?",["Vitamin A","Vitamin D","Vitamin E","Vitamin K"],"Deficiency causes xerophthalmia, Bitot spots and keratomalacia."],["q-fcps-bio5-57","Pantothenic acid is a component of:",["Coenzyme A","FAD","NAD","Thiamine pyrophosphate"],"CoA is needed for acyl transfer, such as in acetyl-CoA formation."],["q-fcps-bio5-58","Iodine deficiency in a population is associated with:",["Endemic goitre and cretinism","Pellagra","Beriberi","Scurvy"],"Iodine is needed for synthesis of thyroid hormones, and its deficiency in pregnancy causes neurological damage in the infant."],["q-fcps-bio5-59","Excess fluoride in drinking water causes:",["Mottled enamel (dental fluorosis)","Rickets","Goitre","Anaemia"],"Low fluoride intake predisposes to dental caries."],["q-fcps-bio5-60","The glycaemic index measures:",["The effect of a food on blood glucose compared with glucose","Calorie content","Protein quality","Fibre content"],"Foods with a high glycaemic index raise blood glucose more rapidly."],["q-fcps-bio5-61","A negative nitrogen balance occurs in:",["Starvation and severe illness","Growth","Pregnancy","Recovery from illness"],"Excretion exceeds intake during catabolic states."],["q-fcps-bio5-62","The respiratory quotient of fat oxidation is about:",["0.7","1.0","0.85","1.3"],"Fat oxidation consumes more oxygen than the carbon dioxide it produces; carbohydrate gives 1.0 and protein about 0.8."],["q-fcps-bio5-63","Which of the following is a ketone body?",["Beta-hydroxybutyrate","Pyruvate","Oxaloacetate","Citrate"],"Acetoacetate, beta-hydroxybutyrate and acetone are the ketone bodies, and the nitroprusside test detects only acetoacetate and acetone."],["q-fcps-bio5-64","In diabetic ketoacidosis the ratio of beta-hydroxybutyrate to acetoacetate rises because of:",["A high NADH/NAD+ ratio","A low NADH/NAD+ ratio","Increased insulin","Decreased lipolysis"],"Excess fatty acid oxidation generates NADH, which favours the reduction of acetoacetate."],["q-fcps-bio5-65","The Na+/K+ ATPase is inhibited by:",["Digoxin and ouabain","Furosemide","Omeprazole","Thiazides"],"Cardiac glycosides inhibit the alpha subunit, raising intracellular sodium and calcium."],["q-fcps-bio5-66","Which G protein stimulates phospholipase C?",["Gq","Gs","Gi","Golf"],"Gs activates adenylyl cyclase and Gi inhibits it."],["q-fcps-bio5-67","The JAK-STAT pathway is used by:",["Cytokine and growth hormone receptors","Insulin receptors","Steroid receptors","Adrenergic receptors"],"Receptor-associated JAKs phosphorylate STATs, which dimerise and enter the nucleus."],["q-fcps-bio5-68","Steroid hormone receptors act by:",["Binding DNA hormone response elements and altering transcription","Activating adenylyl cyclase","Opening ion channels","Activating tyrosine kinases"],"Lipophilic hormones diffuse through the membrane and bind intracellular receptors."],["q-fcps-bio5-69","Insulin receptors signal through:",["Intrinsic tyrosine kinase activity","G proteins","Guanylyl cyclase","Ion channels"],"Autophosphorylation recruits IRS proteins and activates PI3K and MAP kinase pathways."],["q-fcps-bio5-70","Which acute-phase protein is the most sensitive marker of acute inflammation and increases within hours?",["C-reactive protein","Albumin","Transferrin","Ceruloplasmin"],"Albumin and transferrin are negative acute-phase proteins, and they fall in inflammation."],["q-fcps-bio5-71","Which immunoglobulin crosses the placenta?",["IgG","IgM","IgA","IgE"],"IgM is a pentamer that is the first antibody produced in a primary response, and secretory IgA is found in breast milk."],["q-fcps-bio5-72","The Fc region of immunoglobulin determines:",["Biological function such as complement binding and receptor binding","Antigen binding","Light chain type","Idiotype"],"The Fab region contains the antigen-binding site."],["q-fcps-bio5-73","Cytochrome P450 enzymes are located mainly in the:",["Smooth endoplasmic reticulum of hepatocytes","Mitochondria only","Cytosol","Lysosomes"],"Phase I reactions (oxidation) add polar groups, and phase II reactions conjugate with glucuronide, sulphate or glutathione."],["q-fcps-bio5-74","Which conjugation reaction is deficient in neonates and may cause grey baby syndrome with chloramphenicol?",["Glucuronidation","Acetylation","Sulphation","Methylation"],"Immature UDP-glucuronosyltransferase also contributes to physiological neonatal jaundice."],["q-fcps-bio5-75","Leber hereditary optic neuropathy and MELAS are examples of:",["Mitochondrial DNA disorders","Peroxisomal disorders","Lysosomal storage disorders","Trinucleotide repeat disorders"],"They show maternal inheritance and heteroplasmy, which accounts for the variable severity."],["q-fcps-bio6-01","Which amino acid has an imidazole side chain and acts as a buffer at physiological pH?",["Histidine","Lysine","Arginine","Tyrosine"],"The pKa of its side chain is about 6, near physiological pH."],["q-fcps-bio6-02","Which amino acids are acidic?",["Aspartate and glutamate","Lysine and arginine","Serine and threonine","Valine and leucine"],"Lysine, arginine and histidine are basic."],["q-fcps-bio6-03","The isoelectric point (pI) of a protein is the pH at which it:",["Has no net charge and is least soluble","Is fully denatured","Has maximum charge","Is most soluble"],"Proteins precipitate most easily at the pI."],["q-fcps-bio6-04","Which bond stabilises the alpha helix?",["Hydrogen bonds between backbone C=O and N-H","Disulphide bonds","Ionic bonds between side chains","Peptide bonds"],"Proline is a helix breaker because of its ring structure."],["q-fcps-bio6-05","Disulphide bonds are formed between:",["Cysteine residues","Methionine residues","Serine residues","Histidine residues"],"They stabilise tertiary and quaternary structure, particularly in extracellular proteins."],["q-fcps-bio6-06","Prion diseases involve a conformational change from:",["Alpha helix to beta sheet","Beta sheet to alpha helix","Random coil to alpha helix","Beta turn to coil"],"The abnormal protein is protease-resistant and propagates by templating."],["q-fcps-bio6-07","Collagen's unique triple helix has which repeating sequence?",["Gly-X-Y","Ala-X-Y","Cys-X-Y","Pro-X-Gly only"],"Glycine is at every third position because it is small enough to fit the centre."],["q-fcps-bio6-08","Hydroxylation of proline and lysine in collagen requires:",["Vitamin C","Vitamin K","Vitamin B6","Vitamin E"],"Scurvy causes defective collagen and bleeding gums."],["q-fcps-bio6-09","Osteogenesis imperfecta is most commonly due to mutation in:",["Type I collagen genes","Type II collagen","Type III collagen","Elastin"],"Blue sclerae, brittle bones and hearing loss are typical."],["q-fcps-bio6-10","Ehlers-Danlos syndrome (vascular type) involves a defect in:",["Type III collagen","Type I collagen","Fibrillin-1","Type II collagen"],"Fibrillin-1 mutation causes Marfan syndrome."],["q-fcps-bio6-11","Michaelis constant (Km) is:",["The substrate concentration at which the velocity is half of Vmax","The maximum velocity","The enzyme concentration","The inhibitor constant"],"A low Km means high affinity."],["q-fcps-bio6-12","In competitive inhibition:",["Km increases and Vmax is unchanged","Km is unchanged and Vmax falls","Both fall","Both rise"],"In non-competitive inhibition Vmax falls with the same Km."],["q-fcps-bio6-13","On a Lineweaver-Burk plot, the x-intercept is:",["-1/Km","1/Vmax","-1/Vmax","Km"],"The y-intercept is 1/Vmax."],["q-fcps-bio6-14","Methotrexate is an example of a:",["Competitive inhibitor of dihydrofolate reductase","Suicide inhibitor","Non-competitive inhibitor","Uncompetitive inhibitor"],"Aspirin is an irreversible inhibitor of cyclooxygenase."],["q-fcps-bio6-15","Allosteric enzymes show a:",["Sigmoidal velocity curve","Hyperbolic curve","Linear curve","Bell-shaped curve"],"Cooperative binding gives the S-shape."],["q-fcps-bio6-16","Which enzyme is raised first in myocardial infarction?",["Troponin and CK-MB","LDH","AST","ALP"],"Troponin remains elevated for 7 to 14 days and is the preferred marker."],["q-fcps-bio6-17","Which isoenzyme of LDH predominates in the heart?",["LDH-1","LDH-5","LDH-3","LDH-2 only"],"A 'flipped' LDH1 greater than LDH2 pattern suggests infarction."],["q-fcps-bio6-18","Alkaline phosphatase is raised in:",["Obstructive jaundice and bone disease","Hepatitis only","Myocardial infarction","Pancreatitis"],"Paget disease and healing fractures raise ALP of bone origin."],["q-fcps-bio6-19","Gamma-glutamyl transferase helps to:",["Show that raised ALP is of hepatic origin","Diagnose myocardial infarction","Diagnose pancreatitis","Diagnose muscle disease"],"It is also raised by alcohol and enzyme-inducing drugs."],["q-fcps-bio6-20","Amylase and lipase are raised in:",["Acute pancreatitis","Appendicitis","Peptic ulcer perforation only","Cholestasis"],"Lipase is more specific and remains raised longer."],["q-fcps-bio6-21","The rate-limiting enzyme of cholesterol synthesis is:",["HMG-CoA reductase","HMG-CoA synthase","Squalene synthase","Mevalonate kinase"],"Statins inhibit it, and it is also regulated by insulin and SREBP."],["q-fcps-bio6-22","Cholesterol is converted in the body to all of the following EXCEPT:",["Cortisol-binding globulin","Bile acids","Steroid hormones","Vitamin D"],"Cortisol-binding globulin is a protein."],["q-fcps-bio6-23","Which apolipoprotein activates LCAT?",["Apo A-I","Apo B-100","Apo C-II","Apo E"],"LCAT esterifies cholesterol in HDL."],["q-fcps-bio6-24","Familial hypercholesterolaemia is due to a defect in the:",["LDL receptor","HMG-CoA reductase","Lipoprotein lipase","ApoA-I"],"Tendon xanthomata and premature coronary disease are features."],["q-fcps-bio6-25","Carnitine is needed for:",["Transport of long-chain fatty acids into mitochondria","Fatty acid synthesis","Ketone synthesis","Cholesterol synthesis"],"Carnitine palmitoyltransferase I is the rate-limiting step of beta-oxidation and is inhibited by malonyl-CoA."],["q-fcps-bio6-26","Fatty acid synthesis takes place in the:",["Cytosol","Mitochondria","Peroxisomes","Lysosomes"],"Beta-oxidation takes place in mitochondria."],["q-fcps-bio6-27","The NADPH needed for fatty acid synthesis is produced mainly by:",["The pentose phosphate pathway","Glycolysis","The TCA cycle","Beta-oxidation"],"G6PD is the rate-limiting enzyme of this pathway."],["q-fcps-bio6-28","Which essential fatty acid is the precursor of arachidonic acid?",["Linoleic acid","Oleic acid","Palmitic acid","Stearic acid"],"Alpha-linolenic acid is the omega-3 essential fatty acid."],["q-fcps-bio6-29","Refsum disease results from defective:",["Alpha-oxidation of phytanic acid","Beta-oxidation of short-chain fatty acids","Omega-oxidation","Ketogenesis"],"It causes retinitis pigmentosa, ataxia and neuropathy."],["q-fcps-bio6-30","Zellweger syndrome is a disorder of:",["Peroxisomes","Lysosomes","Mitochondria","Golgi apparatus"],"Very long chain fatty acids accumulate."],["q-fcps-bio6-31","Tay-Sachs disease is due to deficiency of:",["Hexosaminidase A","Beta-glucocerebrosidase","Sphingomyelinase","Alpha-galactosidase A"],"It gives a cherry-red macula and no hepatosplenomegaly."],["q-fcps-bio6-32","Gaucher disease is due to deficiency of:",["Glucocerebrosidase","Hexosaminidase A","Sphingomyelinase","Galactocerebrosidase"],"Crumpled tissue paper macrophages and hepatosplenomegaly with bone pain are features."],["q-fcps-bio6-33","Niemann-Pick disease is due to deficiency of:",["Sphingomyelinase","Glucocerebrosidase","Hexosaminidase A","Arylsulphatase A"],"Foam cells and a cherry-red spot are seen."],["q-fcps-bio6-34","Fabry disease is X-linked and results from deficiency of:",["Alpha-galactosidase A","Beta-galactosidase","Hexosaminidase B","Iduronidase"],"Features include angiokeratomas, burning pain in the extremities and renal failure."],["q-fcps-bio6-35","Hurler syndrome is deficiency of:",["Alpha-L-iduronidase","Iduronate sulphatase","Glucocerebrosidase","Hexosaminidase"],"Hunter syndrome is X-linked, and clouding of the cornea is absent in it."],["q-fcps-bio6-36","I-cell disease is due to a defect in:",["Phosphotransferase that adds mannose 6-phosphate to lysosomal enzymes","Glycosylation of collagen","Lysosomal acid lipase","Proteasome function"],"Lysosomal enzymes are secreted outside the cell instead of reaching lysosomes."],["q-fcps-bio6-37","McArdle disease is a deficiency of:",["Muscle glycogen phosphorylase","Glucose 6-phosphatase","Acid maltase","Branching enzyme"],"It causes exercise intolerance with no rise in lactate."],["q-fcps-bio6-38","Von Gierke disease is a deficiency of:",["Glucose 6-phosphatase","Debranching enzyme","Liver phosphorylase","Muscle phosphorylase"],"It presents with severe fasting hypoglycaemia, lactic acidosis, hyperuricaemia and hepatomegaly."],["q-fcps-bio6-39","Essential fructosuria is due to deficiency of:",["Fructokinase","Aldolase B","Aldose reductase","Hexokinase"],"It is benign, while hereditary fructose intolerance (aldolase B) causes hypoglycaemia and liver damage."],["q-fcps-bio6-40","Classic galactosaemia is due to deficiency of:",["Galactose 1-phosphate uridyltransferase","Galactokinase","UDP-galactose epimerase","Lactase"],"Infants develop jaundice, cataracts and E. coli sepsis after milk feeds."],["q-fcps-bio6-41","Lactose intolerance results from deficiency of:",["Lactase in the brush border","Sucrase","Maltase","Amylase"],"It causes osmotic diarrhoea and a positive hydrogen breath test."],["q-fcps-bio6-42","Maple syrup urine disease results from a defect in:",["Branched-chain alpha-ketoacid dehydrogenase","Phenylalanine hydroxylase","Homogentisate oxidase","Cystathionine synthase"],"Leucine, isoleucine and valine accumulate, and thiamine can help."],["q-fcps-bio6-43","Alkaptonuria results from deficiency of:",["Homogentisate oxidase","Tyrosinase","Phenylalanine hydroxylase","Fumarylacetoacetase"],"Urine darkens on standing, and patients develop ochronosis and arthritis."],["q-fcps-bio6-44","Homocystinuria due to cystathionine beta-synthase deficiency features:",["Ectopia lentis (downward), thrombosis and intellectual disability","Upward lens dislocation as in Marfan","Aortic dissection","Hypopigmentation only"],"The lens dislocates downward in homocystinuria and upward in Marfan syndrome."],["q-fcps-bio6-45","Cystinuria results from a defect in renal transport of:",["Cystine, ornithine, lysine and arginine (COLA)","Neutral amino acids","Glycine","Dicarboxylic amino acids"],"Hexagonal cystine stones form, and the urine nitroprusside test is positive."],["q-fcps-bio6-46","Hyperphenylalaninaemia that does not respond to dietary restriction suggests a defect in:",["Tetrahydrobiopterin synthesis or recycling","Phenylalanine hydroxylase","Tyrosinase","Homogentisate oxidase"],"Tetrahydrobiopterin is also needed for tyrosine and tryptophan hydroxylation, so neurotransmitter synthesis fails."],["q-fcps-bio6-47","A newborn with PKU should be given a diet low in:",["Phenylalanine","Tyrosine","Leucine","Methionine"],"Untreated children have musty odour, fair skin and intellectual disability."],["q-fcps-bio6-48","Which enzyme deficiency leads to orotic aciduria?",["UMP synthase","OTC","Xanthine oxidase","HGPRT"],"Megaloblastic anaemia does not respond to B12 or folate, and uridine is the treatment."],["q-fcps-bio6-49","Ornithine transcarbamylase deficiency differs from other urea cycle defects in that it:",["Is X-linked with raised orotic acid","Is autosomal recessive with low orotic acid","Presents only in adults","Has no hyperammonaemia"],"Orotic acid is raised because carbamoyl phosphate spills into pyrimidine synthesis."],["q-fcps-bio6-50","Lesch-Nyhan syndrome is due to deficiency of:",["HGPRT","APRT","Adenosine deaminase","PRPP synthetase"],"Features are self-mutilation, gout, intellectual disability and dystonia."],["q-fcps-bio6-51","Which vitamin is a coenzyme for transaminases and decarboxylases?",["Pyridoxal phosphate (B6)","Thiamine","Biotin","Riboflavin"],"Isoniazid and pyridoxine deficiency cause sideroblastic anaemia and neuropathy."],["q-fcps-bio6-52","Thiamine pyrophosphate is a coenzyme of:",["Pyruvate dehydrogenase and transketolase","Carboxylases","Transaminases","Methyltransferases"],"Wernicke encephalopathy is treated with thiamine before glucose."],["q-fcps-bio6-53","The Wernicke triad includes:",["Confusion, ophthalmoplegia and ataxia","Dementia, diarrhoea and dermatitis","Fever, rash and arthritis","Ataxia, tremor and nystagmus only"],"Dementia, diarrhoea and dermatitis are the features of pellagra."],["q-fcps-bio6-54","Riboflavin is a component of:",["FAD and FMN","NAD and NADP","Coenzyme A","TPP"],"Deficiency causes angular stomatitis, cheilosis and glossitis."],["q-fcps-bio6-55","Biotin deficiency may be caused by excess intake of:",["Raw egg white (avidin)","Alcohol","Vitamin C","Cooked egg"],"Biotin is the coenzyme of carboxylases."],["q-fcps-bio6-56","Folate deficiency in early pregnancy increases the risk of:",["Neural tube defects","Rickets","Cleft palate only","Cardiac defects only"],"Folate is needed for thymidylate synthesis."],["q-fcps-bio6-57","The 'trap' hypothesis of folate: methyl tetrahydrofolate accumulates in deficiency of:",["Vitamin B12","Vitamin B6","Vitamin C","Thiamine"],"Methionine synthase needs B12 to regenerate tetrahydrofolate."],["q-fcps-bio6-58","Methylmalonic aciduria is seen in deficiency of:",["Vitamin B12","Folate","Vitamin B6","Biotin"],"Methylmalonyl-CoA mutase requires adenosylcobalamin, and a raised methylmalonic acid distinguishes B12 from folate deficiency."],["q-fcps-bio6-59","Vitamin K is needed for:",["Gamma-carboxylation of clotting factors","Hydroxylation of collagen","Transamination","Rhodopsin synthesis"],"Newborns are given vitamin K to prevent haemorrhagic disease."],["q-fcps-bio6-60","Vitamin E acts as:",["A lipid-soluble antioxidant","A coenzyme in carboxylation","A calcium regulator","A visual pigment"],"Deficiency causes haemolytic anaemia and neuropathy."],["q-fcps-bio6-61","Rickets in children is caused by deficiency of:",["Vitamin D","Vitamin C","Vitamin A","Vitamin K"],"Low calcium and phosphate cause defective mineralisation of the growth plate."],["q-fcps-bio6-62","Which finding is typical in vitamin D-resistant (X-linked hypophosphataemic) rickets?",["Low serum phosphate with normal calcium","Low calcium and high phosphate","Low PTH","High calcium"],"It is due to a PHEX mutation and FGF23 excess."],["q-fcps-bio6-63","Selenium deficiency is associated with:",["Keshan cardiomyopathy","Goitre","Pellagra","Beriberi"],"Selenium is a component of glutathione peroxidase."],["q-fcps-bio6-64","Wilson disease involves a defect in:",["ATP7B copper transport","ATP7A","Ceruloplasmin gene only","Ferroportin"],"Kayser-Fleischer rings, low ceruloplasmin and raised urinary copper are typical."],["q-fcps-bio6-65","Menkes disease is due to a defect in:",["ATP7A copper transport","ATP7B","Ferritin","Hepcidin"],"It gives kinky hair, X-linked inheritance and neurodegeneration."],["q-fcps-bio6-66","Hepcidin:",["Reduces iron absorption by degrading ferroportin","Increases iron absorption","Is made by the kidney","Is reduced in chronic inflammation"],"Hepcidin is raised in inflammation, causing anaemia of chronic disease."],["q-fcps-bio6-67","Haemochromatosis (HFE type) is most commonly associated with:",["C282Y mutation","F508 deletion","V617F mutation","R506Q mutation"],"It causes bronze diabetes, cirrhosis and cardiomyopathy and is treated with venesection."],["q-fcps-bio6-68","In the synthesis of haem, the rate-limiting enzyme is:",["ALA synthase","Ferrochelatase","ALA dehydratase","Porphobilinogen deaminase"],"It requires pyridoxal phosphate and glycine."],["q-fcps-bio6-69","Lead poisoning inhibits:",["ALA dehydratase and ferrochelatase","ALA synthase only","Uroporphyrinogen decarboxylase","HMB synthase"],"Basophilic stippling and raised urinary ALA are seen."],["q-fcps-bio6-70","Acute intermittent porphyria is due to deficiency of:",["Porphobilinogen deaminase (HMB synthase)","Ferrochelatase","Uroporphyrinogen decarboxylase","ALA dehydratase"],"It causes abdominal pain and neuropsychiatric symptoms without photosensitivity."],["q-fcps-bio6-71","Porphyria cutanea tarda presents with:",["Blistering photosensitive skin lesions","Acute abdominal pain","Neuropathy only","Anaemia only"],"It is the commonest porphyria and is due to uroporphyrinogen decarboxylase deficiency."],["q-fcps-bio6-72","Unconjugated hyperbilirubinaemia is seen in:",["Gilbert syndrome and Crigler-Najjar syndrome","Dubin-Johnson syndrome","Rotor syndrome","Biliary obstruction"],"Dubin-Johnson and Rotor syndromes cause conjugated hyperbilirubinaemia."],["q-fcps-bio6-73","Bilirubin in the urine indicates:",["Conjugated hyperbilirubinaemia","Unconjugated hyperbilirubinaemia","Haemolysis alone","Gilbert syndrome"],"Unconjugated bilirubin is bound to albumin and is not filtered."],["q-fcps-bio6-74","In haemolytic jaundice, urinary urobilinogen is:",["Increased","Absent","Normal","Decreased"],"It is absent in complete biliary obstruction."],["q-fcps-bio6-75","Kernicterus occurs in neonates because unconjugated bilirubin:",["Crosses the immature blood-brain barrier and deposits in the basal ganglia","Is excreted in bile","Binds to bile acid","Is water-soluble"],"Phototherapy converts it to water-soluble isomers."],["q-fcps-bio6-76","Which plasma protein is the main carrier of copper?",["Ceruloplasmin","Transferrin","Haptoglobin","Albumin"],"It is also a ferroxidase."],["q-fcps-bio6-77","Haptoglobin is reduced in:",["Intravascular haemolysis","Acute inflammation","Nephrotic syndrome","Pregnancy"],"It binds free haemoglobin."],["q-fcps-bio6-78","The best indicator of long-term glycaemic control is:",["HbA1c","Fasting glucose","Random glucose","Urine glucose"],"It reflects the previous 8 to 12 weeks, and it is unreliable in haemolysis and haemoglobinopathies."],["q-fcps-bio6-79","The ketone body not detected by the urine nitroprusside test is:",["Beta-hydroxybutyrate","Acetoacetate","Acetone","None of these"],"It may underestimate severity in DKA."],["q-fcps-bio6-80","Which test is used to confirm hypothyroidism of primary origin?",["Raised TSH with low free T4","Low TSH with low free T4","Raised TSH with raised free T4","Low TSH with raised free T4"],"Secondary hypothyroidism has a low or inappropriately normal TSH."],["q-fcps-bio6-81","Sodium is the major cation of:",["Extracellular fluid","Intracellular fluid","Cytosol","Mitochondria"],"Potassium is the major intracellular cation."],["q-fcps-bio6-82","Osmolality of plasma is approximately:",["285 to 295 mOsm/kg","150 mOsm/kg","400 mOsm/kg","500 mOsm/kg"],"Estimated as 2 times sodium plus glucose over 18 plus urea over 2.8."],["q-fcps-bio6-83","Pseudohyponatraemia may be caused by:",["Severe hypertriglyceridaemia","Hyperglycaemia","Mannitol","Dehydration"],"Hyperglycaemia causes true hyponatraemia by water shift."],["q-fcps-bio6-84","Hypocalcaemia causes:",["Tetany with a positive Chvostek sign and Trousseau sign","Polyuria","Constipation and stones","Short QT interval"],"Chvostek is facial twitching on tapping the facial nerve, and Trousseau is carpal spasm with a cuff."]];
